def ipv4_ke_biner(ip_str):
    if not isinstance(ip_str, str):
        return None
    bagian = ip_str.strip().split('.')
    if len(bagian) != 4:
        return None
    oktet_biner = []
    for b in bagian:
        if not b.isdigit():
            return None
        val = int(b)
        if val < 0 or val > 255:
            return None
        oktet_biner.append(format(val, '08b'))
    return '.'.join(oktet_biner)

