def kompres_ipv6(alamat):
    grup = [g.lstrip('0').lower() or '0' for g in alamat.strip().split(':')]
    best_start, best_len = -1, 0
    cur_start, cur_len = -1, 0
    for i, g in enumerate(grup):
        if g == '0':
            if cur_start == -1:
                cur_start, cur_len = i, 1
            else:
                cur_len += 1
            if cur_len > best_len:
                best_start, best_len = cur_start, cur_len
        else:
            cur_start, cur_len = -1, 0

    if best_len < 2:
        return ':'.join(grup)
    kiri = ':'.join(grup[:best_start])
    kanan = ':'.join(grup[best_start + best_len:])
    return f'{kiri}::{kanan}'

