def hitung_raid(level, n_disk, ukuran_gb):
    lvl = level.upper()
    if ukuran_gb <= 0:
        return None
    if lvl == 'RAID0' and n_disk >= 2:
        return {'kapasitas_gb': n_disk * ukuran_gb, 'toleransi_gagal': 0}
    if lvl == 'RAID1' and n_disk >= 2:
        return {'kapasitas_gb': ukuran_gb, 'toleransi_gagal': n_disk - 1}
    if lvl == 'RAID5' and n_disk >= 3:
        return {'kapasitas_gb': (n_disk - 1) * ukuran_gb, 'toleransi_gagal': 1}
    if lvl == 'RAID10' and n_disk >= 4 and n_disk % 2 == 0:
        return {'kapasitas_gb': (n_disk // 2) * ukuran_gb, 'toleransi_gagal': 1}
    return None

