practice_labs.solution_code:
def ekspansi_ipv6(alamat):
    s = alamat.strip().lower()
    if s.count('::') > 1:
        return None
    if '::' in s:
        kiri_str, kanan_str = s.split('::')
        kiri = kiri_str.split(':') if kiri_str else []
        kanan = kanan_str.split(':') if kanan_str else []
        sisa = 8 - (len(kiri) + len(kanan))
        if sisa < 1:
            return None
        grup = kiri + ['0000'] * sisa + kanan
    else:
        grup = s.split(':')
        if len(grup) != 8:
            return None
    return ':'.join(g.zfill(4) for g in grup)

