def hitung_risiko_aset(daftar_aset):
    hasil = []
    for item in daftar_aset:
        skor = item['nilai_aset'] * item['ancaman'] * item['kerentanan']
        if skor >= 75:
            lvl = 'Kritis'
        elif skor >= 40:
            lvl = 'Tinggi'
        elif skor >= 15:
            lvl = 'Sedang'
        else:
            lvl = 'Rendah'
        hasil.append({'nama': item['nama'], 'skor_risiko': skor, 'level': lvl})
    hasil.sort(key=lambda x: (-x['skor_risiko'], x['nama']))
    return hasil

