import ipaddress

def satu_subnet(ip1_cidr, ip2_cidr):
    n1 = ipaddress.IPv4Interface(ip1_cidr).network
    n2 = ipaddress.IPv4Interface(ip2_cidr).network
    return n1 == n2

def ada_subnet_overlap(daftar_cidr):
    nets = [ipaddress.IPv4Network(c, strict=False) for c in daftar_cidr]
    for i in range(len(nets)):
        for j in range(i + 1, len(nets)):
            if nets[i].overlaps(nets[j]):
                return True
    return False

