import ipaddress

def audit_server_ubuntu(cfg):
    temuan = []
    iface = ipaddress.IPv4Interface(cfg['server_cidr'])
    net = iface.network
    srv = iface.ip
    gw = ipaddress.IPv4Address(cfg['gateway'])
    s = ipaddress.IPv4Address(cfg['dhcp_start'])
    e = ipaddress.IPv4Address(cfg['dhcp_end'])

    if net.prefixlen < 31 and (srv == net.network_address or srv == net.broadcast_address):
        temuan.append('IP server tidak valid (network/broadcast)')
    if gw not in net:
        temuan.append('Gateway di luar subnet')
    if s > e or (s not in net) or (e not in net) or (s <= srv <= e) or (s <= gw <= e):
        temuan.append('Konflik pool DHCP dengan server/gateway')
    if not str(cfg.get('dhcp_interface', '')).strip():
        temuan.append('Interface DHCP kosong')
    if not str(cfg.get('bind_zone_path', '')).startswith('/etc/bind/'):
        temuan.append('Errata path BIND9 (harus /etc/bind/)')
    oktet = str(srv).split('.')
    expected_rev = f'{oktet[2]}.{oktet[1]}.{oktet[0]}.in-addr.arpa'
    if cfg.get('reverse_zone', '').strip() != expected_rev:
        temuan.append('Format reverse zone salah')

    return {'siap_produksi': len(temuan) == 0, 'temuan': temuan}
